package com.hozefa.threepattipro.nativeapp;
import org.junit.Test;
import java.time.Instant;
import java.util.*;
import static org.junit.Assert.*;

public class AdvancedAnalyticsTest {
    private Map<String,Object> row(Object... values){Map<String,Object> out=new LinkedHashMap<>();for(int i=0;i<values.length;i+=2)out.put((String)values[i],values[i+1]);return out;}
    private Map<String,Object> round(int n,String result,long a,long b,long c){return row("id",String.format(Locale.ROOT,"r%03d",n),"type","hukum","timestamp",Instant.ofEpochSecond(1000+n).toString(),"result",result,"hukumId","a","hukumName","A","partnerIds",Arrays.asList("b"),"partnerNames",Arrays.asList("B"),"nonPartnerIds",Arrays.asList("c"),"nonPartnerNames",Arrays.asList("C"),"playerIds",Arrays.asList("a","b","c"),"bid",155,"scoreChanges",row("a",a,"b",b,"c",c));}
    private List<Map<String,Object>> roster(){return Arrays.asList(row("id","a","name","A"),row("id","b","name","B"),row("id","c","name","C"),row("id","ghost","name","Never played"));}
    private AdvancedAnalytics.Report report(Map<String,Object>... rounds){return new AdvancedAnalytics.Report(roster(),Arrays.asList(rounds),Collections.emptyList());}
    private List<Map<String,Object>> metadata(){return Arrays.asList(row("id","old","sessionName","Old","startTime",Instant.ofEpochSecond(1000).toString(),"endTime",Instant.ofEpochSecond(1003).toString()),row("id","current","sessionName","Current","startTime",Instant.ofEpochSecond(1003).toString(),"endTime",null));}
    @Test public void excludesSettlementsAndPracticeWithoutMutatingSource(){Map<String,Object> real=round(1,"win",10,5,0),settle=round(2,"win",900,0,0),practice=round(3,"win",900,0,0);settle.put("type","settlement");practice.put("isPractice",true);AdvancedAnalytics.Report r=report(practice,real,settle);assertEquals(1,r.rounds.size());assertEquals(10,r.players.get("a").points);assertEquals(900,AdvancedAnalytics.delta(practice,"a"));}
    @Test public void handlesEveryPracticeMarker(){for(String key:Arrays.asList("type","mode","source","practice","isPractice")){Map<String,Object> r=round(1,"win",10,5,0);r.put(key,key.equals("practice")||key.equals("isPractice")?true:"practice");assertFalse(AdvancedAnalytics.eligible(r));}}
    @Test public void zeroPointOpponentCanWin(){AdvancedAnalytics.Stats s=report(round(1,"loss",-10,-5,0)).players.get("c");assertEquals(1,s.wins);assertEquals(0,s.losses);assertEquals(0,s.points);assertEquals(100,s.rate(),0);}
    @Test public void unknownResultsNeverBecomeOpponentWins(){AdvancedAnalytics.Stats s=report(round(1,"pending",0,0,0)).players.get("c");assertEquals(0,s.decided());assertEquals(1,s.unknown);assertTrue(Double.isNaN(s.rate()));}
    @Test public void missingHukumIsUnknownOutcome(){Map<String,Object> r=round(1,"loss",0,0,0);r.put("hukumId","missing");assertEquals(0,AdvancedAnalytics.result(r,"c"));}
    @Test public void statisticsAreChronologicalDespiteInputOrder(){AdvancedAnalytics.Report r=report(round(3,"win",7,0,0),round(1,"loss",-5,0,0),round(2,"win",3,0,0));AdvancedAnalytics.Stats s=r.players.get("a");assertEquals(Arrays.asList(0L,-5L,-2L,5L),s.cumulative);assertEquals(2,s.currentWins);assertEquals(2,s.longestWins);}
    @Test public void roleStatsHaveTheirOwnDenominators(){Map<String,Object> second=round(2,"loss",0,10,-5);second.put("hukumId","b");second.put("partnerIds",Arrays.asList("c"));AdvancedAnalytics.Report r=report(round(1,"win",10,5,0),second);assertEquals(1,r.roleStats("a","Hukum").played);assertEquals(1,r.roleStats("a","Opponent").wins);assertEquals(0,r.roleStats("a","Partner").played);}
    @Test public void absenceDoesNotBreakStreakButUnknownDoes(){Map<String,Object> missing=round(2,"loss",0,0,0);missing.put("playerIds",Arrays.asList("b","c"));AdvancedAnalytics.Report r=report(round(1,"win",10,0,0),missing,round(3,"win",10,0,0),round(4,"pending",0,0,0),round(5,"loss",-10,0,0));assertEquals(2,r.players.get("a").longestWins);assertEquals(1,r.players.get("a").currentLosses);assertEquals(0,r.players.get("a").currentWins);}
    @Test public void longTotalsDoNotOverflowInt(){AdvancedAnalytics.Stats s=report(round(1,"win",2000000000L,0,0),round(2,"win",2000000000L,0,0)).players.get("a");assertEquals(4000000000L,s.points);assertEquals(2000000000d,s.average,0);}
    @Test public void allNegativeRecordsStayNegative(){AdvancedAnalytics.Stats s=report(round(1,"loss",-5,0,0),round(2,"loss",-10,0,0)).players.get("a");assertEquals(-5,s.bestRound);assertEquals(-10,s.worstRound);assertEquals(15,s.lost);assertEquals(0,s.gained);}
    @Test public void variationUsesPlayedRoundDeltas(){AdvancedAnalytics.Stats s=report(round(1,"loss",-10,0,0),round(2,"win",10,0,0)).players.get("a");assertEquals(10,s.variation,0.0001);assertEquals(0,s.average,0);}
    @Test public void emptyStatsAreFiniteAndRatesUndefined(){AdvancedAnalytics.Stats s=report().players.get("a");assertEquals(0,s.played);assertEquals(0,s.average,0);assertEquals(0,s.variation,0);assertTrue(Double.isNaN(s.rate()));assertTrue(s.limited());}
    @Test public void formUsesOwnPlayedRoundsAndNonOverlappingWindows(){List<Map<String,Object>> rounds=new ArrayList<>();for(int i=1;i<=12;i++)rounds.add(round(i,"win",i,0,0));AdvancedAnalytics.Form f=new AdvancedAnalytics.Report(roster(),rounds,Collections.emptyList()).form("a",5);assertEquals(10,f.now.average,0);assertEquals(5,f.before.average,0);assertTrue(f.comparable(5));assertEquals(8,AdvancedAnalytics.delta(f.recent.get(0),"a"));assertEquals(7,AdvancedAnalytics.delta(f.previous.get(4),"a"));}
    @Test public void partialFormNeverClaimsFullComparison(){AdvancedAnalytics.Form f=report(round(1,"win",5,0,0)).form("a",10);assertFalse(f.comparable(10));assertEquals(1,f.now.played);assertEquals(0,f.before.played);}
    @Test public void bidsOnlyIncludeCallingPlayerAndSavedPoints(){Map<String,Object> r=round(2,"loss",0,20,0);r.put("hukumId","b");r.put("partnerIds",Arrays.asList("a"));AdvancedAnalytics.Report report=report(round(1,"win",321,0,0),r);assertEquals(1,report.bids("a").get(155L).played);assertEquals(321,report.bids("a").get(155L).points);}
    @Test public void missingBidIsExplicitUnspecifiedBucket(){Map<String,Object> r=round(1,"win",10,0,0);r.remove("bid");assertTrue(report(r).bids("a").containsKey(0L));}
    @Test public void partnershipCountsOnlyCommonHukumTeam(){AdvancedAnalytics.Report r=report(round(1,"win",10,5,0),round(2,"loss",-10,-5,0));List<AdvancedAnalytics.Pair> pairs=r.pairs("a");assertEquals(1,pairs.size());assertEquals("b",pairs.get(0).peer);assertEquals(2,pairs.get(0).rounds);assertEquals(50,pairs.get(0).rate(),0);assertTrue(r.pairs("c").isEmpty());}
    @Test public void partnershipDoesNotCountOnePlayerTwice(){Map<String,Object> r=round(1,"win",10,5,0);r.put("partnerIds",Arrays.asList("b","b"));assertEquals(1,report(r).pairs("a").get(0).rounds);}
    @Test public void neverPlayedRosterCannotBecomeImaginaryLeader(){AdvancedAnalytics.Report r=report(round(1,"loss",-10,-5,-1));assertEquals(Collections.singleton("c"),r.timeline.get(0).leaders);assertFalse(r.timeline.get(0).ranks.containsKey("ghost"));}
    @Test public void tiesUseCompetitionRanksAndLeaderSetChanges(){AdvancedAnalytics.Report r=report(round(1,"win",-10,10,0),round(2,"win",30,-30,0),round(3,"win",-10,30,0));AdvancedAnalytics.Frame f=r.timeline.get(2);assertEquals(1,(int)f.ranks.get("a"));assertEquals(1,(int)f.ranks.get("b"));assertEquals(3,(int)f.ranks.get("c"));assertEquals(2,r.leaderChanges);assertEquals(0,f.margin);}
    @Test public void comebackRequiresRecoveringDeficitToLead(){AdvancedAnalytics.Report r=report(round(1,"loss",-10,10,0),round(2,"win",5,0,0));assertEquals(0L,(long)r.comeback.getOrDefault("a",0L));r=report(round(1,"loss",-10,10,0),round(2,"win",30,-30,0));assertEquals(20L,(long)r.comeback.get("a"));assertEquals(20L,(long)r.highestLead.get("a"));}
    @Test public void roundImpactSeparatesEntriesAndExistingRankMovement(){AdvancedAnalytics.Report r=report(round(1,"loss",-10,10,0),round(2,"win",30,-30,0));assertEquals(0,r.timeline.get(0).movement);assertEquals(4,r.impacts().get(0).movement);assertEquals(2,r.impacts().get(0).moved);assertEquals("r002",AdvancedAnalytics.text(r.impacts().get(0).round,"id"));}
    @Test public void explicitSessionWinsOverTimeInference(){Map<String,Object> r=round(4,"win",10,0,0);r.put("sessionId","old");List<AdvancedAnalytics.Session> sessions=AdvancedAnalytics.groupSessions(Arrays.asList(r),metadata());assertEquals("old",sessions.get(0).id);}
    @Test public void sessionBoundaryIsEndExclusive(){List<AdvancedAnalytics.Session> sessions=AdvancedAnalytics.groupSessions(Arrays.asList(round(2,"win",1,0,0),round(3,"win",1,0,0)),metadata());assertEquals("current",sessions.get(0).id);assertEquals(1,sessions.get(0).rounds.size());assertEquals("old",sessions.get(1).id);assertEquals(1,sessions.get(1).rounds.size());}
    @Test public void legacyOverlappingSessionsUseLatestStart(){List<Map<String,Object>> sessions=new ArrayList<>(metadata());sessions.get(0).put("endTime",Instant.ofEpochSecond(1010).toString());assertEquals("current",AdvancedAnalytics.groupSessions(Arrays.asList(round(4,"win",1,0,0)),sessions).get(0).id);}
    @Test public void unknownSessionAndUndatedRoundsAreNotDropped(){Map<String,Object> r=round(1,"win",1,0,0),other=round(2,"win",1,0,0);r.put("timestamp","bad");other.put("sessionId","deleted-session");List<AdvancedAnalytics.Session> groups=AdvancedAnalytics.groupSessions(Arrays.asList(r,other),metadata());assertEquals(2,groups.size());assertTrue(groups.stream().anyMatch(s->s.name.equals("Unassigned rounds")));assertTrue(groups.stream().anyMatch(s->s.id.equals("deleted-session")));}
    @Test public void sessionScopesIntersectSuppliedDateFilteredRounds(){List<Map<String,Object>> games=Arrays.asList(round(1,"win",1,0,0),round(4,"win",1,0,0));assertEquals(1,AdvancedAnalytics.scope(games,metadata(),"current").size());assertEquals("r001",AdvancedAnalytics.text(AdvancedAnalytics.scope(games,metadata(),"previous").get(0),"id"));assertTrue(AdvancedAnalytics.scope(Arrays.asList(round(4,"win",1,0,0)),metadata(),"previous").isEmpty());}
    @Test public void removedPlayersKeepHistoricalNames(){Map<String,Object> r=round(1,"win",10,5,0);AdvancedAnalytics.Report report=new AdvancedAnalytics.Report(Collections.emptyList(),Arrays.asList(r),Collections.emptyList());assertEquals("A",report.names.get("a"));assertEquals("B",report.names.get("b"));assertEquals(10,report.players.get("a").points);}
    @Test public void limitedInsightsDoNotClaimBestPartnership(){AdvancedAnalytics.Report r=report(round(1,"win",10,5,0));String joined=String.join(" ",r.insights("a",10));assertTrue(joined.contains("limited data"));assertFalse(joined.contains("Highest observed partnership"));assertTrue(joined.contains("Need 20 played rounds"));}
    @Test public void completeFormInsightsQuoteActualWindows(){List<Map<String,Object>> games=new ArrayList<>();for(int i=1;i<=20;i++)games.add(round(i,"win",i<=10?5:15,0,0));AdvancedAnalytics.Report r=new AdvancedAnalytics.Report(roster(),games,Collections.emptyList());String joined=String.join(" ",r.insights("a",10));assertTrue(joined.contains("15.0 points/round"));assertTrue(joined.contains("previous 10: 5.0"));assertTrue(joined.contains("Highest observed partnership"));}
    @Test public void stableTimestampTiesUseDocumentIdOrder(){Map<String,Object> first=round(1,"win",3,0,0),second=round(2,"loss",-1,0,0);second.put("timestamp",first.get("timestamp"));assertEquals("r001",AdvancedAnalytics.text(report(second,first).rounds.get(0),"id"));}
    @Test public void duplicateParticipantIdsDoNotInflateScores(){Map<String,Object> r=round(1,"win",10,5,0);r.put("playerIds",Arrays.asList("a","a","b","c"));AdvancedAnalytics.Report report=report(r);assertEquals(10L,(long)report.timeline.get(0).scores.get("a"));assertEquals(1,report.players.get("a").played);}
    @Test public void todayDoesNotIncludeTomorrow(){Map<String,Object> today=round(1,"win",1,0,0),tomorrow=round(2,"win",1,0,0);today.put("timestamp","2026-10-18T23:59:59Z");tomorrow.put("timestamp","2026-10-19T00:00:00Z");assertEquals(1,AdvancedAnalytics.dates(Arrays.asList(today,tomorrow),"today",Instant.parse("2026-10-18T12:00:00Z"),java.time.ZoneOffset.UTC,0,0).size());}
    @Test public void analyticsCustomEndOnlyIsBounded(){Map<String,Object> first=round(1,"win",1,0,0),later=round(2,"win",1,0,0);first.put("timestamp","2026-10-18T23:59:59Z");later.put("timestamp","2026-10-19T00:00:00Z");assertEquals(1,AdvancedAnalytics.dates(Arrays.asList(first,later),"custom",Instant.now(),java.time.ZoneOffset.UTC,0,Instant.parse("2026-10-18T00:00:00Z").toEpochMilli()).size());}
    @Test public void customDatesRespectDstAndInclusiveCalendarEnd(){Map<String,Object> first=round(1,"win",1,0,0),later=round(2,"win",1,0,0);first.put("timestamp","2026-11-02T04:59:59Z");later.put("timestamp","2026-11-02T05:00:00Z");long day=Instant.parse("2026-11-01T04:00:00Z").toEpochMilli();assertEquals(1,AdvancedAnalytics.dates(Arrays.asList(first,later),"custom",Instant.now(),java.time.ZoneId.of("America/New_York"),day,day).size());}
    @Test public void datesUseDeviceTimezoneAndDiscardUndatedOnlyWhenBounded(){Map<String,Object> localToday=round(1,"win",1,0,0),bad=round(2,"win",1,0,0);localToday.put("timestamp","2026-10-17T19:00:00Z");bad.put("timestamp","bad");assertEquals(1,AdvancedAnalytics.dates(Arrays.asList(localToday,bad),"today",Instant.parse("2026-10-18T12:00:00Z"),java.time.ZoneId.of("Asia/Kolkata"),0,0).size());assertEquals(2,AdvancedAnalytics.dates(Arrays.asList(localToday,bad),"all",Instant.now(),java.time.ZoneOffset.UTC,0,0).size());}
    @Test public void weekEndsAtNextSunday(){Map<String,Object> first=round(1,"win",1,0,0),next=round(2,"win",1,0,0);first.put("timestamp","2026-10-17T23:59:59Z");next.put("timestamp","2026-10-18T00:00:00Z");assertEquals(1,AdvancedAnalytics.dates(Arrays.asList(first,next),"week",Instant.parse("2026-10-17T12:00:00Z"),java.time.ZoneOffset.UTC,0,0).size());}
    @Test public void wellSampledPartnershipPrecedesOneLuckyRound(){List<Map<String,Object>> games=new ArrayList<>();games.add(round(1,"win",10,5,0));for(int i=2;i<=11;i++){Map<String,Object> r=round(i,i<=7?"win":"loss",10,0,0);r.put("playerIds",Arrays.asList("a","d","c"));r.put("partnerIds",Arrays.asList("d"));r.put("partnerNames",Arrays.asList("D"));r.put("scoreChanges",row("a",10,"d",5,"c",0));games.add(r);}List<AdvancedAnalytics.Pair> pairs=new AdvancedAnalytics.Report(roster(),games,Collections.emptyList()).pairs("a");assertEquals("d",pairs.get(0).peer);assertEquals(60,pairs.get(0).rate(),0);assertEquals("b",pairs.get(1).peer);}
    @Test public void formWindowsSkipRoundsWherePlayerWasAbsent(){List<Map<String,Object>> games=new ArrayList<>();for(int i=1;i<=20;i++){Map<String,Object> r=round(i,"win",i,0,0);if(i%2==0)r.put("playerIds",Arrays.asList("b","c","d"));games.add(r);}AdvancedAnalytics.Form f=new AdvancedAnalytics.Report(roster(),games,Collections.emptyList()).form("a",5);assertEquals(15,f.now.average,0);assertEquals(5,f.before.average,0);assertTrue(f.comparable(5));}
}
